import { describe, expect, it } from 'vitest';
import {
  STYLE_DIMENSIONS,
  analyzeStyleCompatibility,
  compileDesignPrompt,
  compileNegativePrompt,
  composeStyleSelection,
  directionFromSelection,
  getStyle,
  parseDesignStyleSelection,
  parseStyleLibrary,
  pendingReferences,
  styleCatalogSnapshot,
  unresolvedDirection,
  type StyleLibrary,
} from '../src/index';
import { StyleSelectionSchema } from '../src/composer';
import { parseModel } from '../src/validation';
import fixtureJson from './fixtures/design-mode.json';

// Generated by services/langgraph/tests/test_design_mode_parity_fixture.py (Python is the reference).
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Raises = { readonly error: string; readonly message?: string; readonly value_errors?: readonly string[] };
type Outcome = { readonly ok?: Json; readonly raises?: Raises };

interface Fixture {
  readonly style_dimensions: readonly string[];
  readonly libraries: { readonly [name: string]: Json };
  readonly library_cases: ReadonlyArray<Outcome & { name: string; input: Json }>;
  readonly lookups: ReadonlyArray<Outcome & { library: string; style_id?: string; pending?: string[] }>;
  readonly style_ids: ReadonlyArray<Outcome & { style_id: string }>;
  readonly compatibility: ReadonlyArray<Outcome & { library: string; style_ids: string[]; brief_text: string; dimension_overlap: boolean }>;
  readonly prompts: ReadonlyArray<{ brief: Json; composed: Json; ok: string }>;
  readonly negatives: ReadonlyArray<{ tokens: string[]; ok: string }>;
  readonly compose: ReadonlyArray<Outcome & { library: string; selections: Json[]; brief: Json }>;
  readonly directions: ReadonlyArray<Outcome & { library: string; selection: Json; brief: Json }>;
  readonly unresolved: ReadonlyArray<Outcome & { selection: Json; reason: string; catalog_version: string | null }>;
  readonly lax_divergences: ReadonlyArray<{ kind: string; input: Json }>;
}

const fixture = fixtureJson as unknown as Fixture;
const libraryCache = new Map<string, StyleLibrary>();

function library(name: string): StyleLibrary {
  const cached = libraryCache.get(name);
  if (cached !== undefined) return cached;
  const parsed = parseStyleLibrary(fixture.libraries[name]);
  libraryCache.set(name, parsed);
  return parsed;
}

/** Run a twin function and describe its failure the way the fixture does. */
function run(fn: () => unknown): Outcome {
  try {
    return { ok: JSON.parse(JSON.stringify(fn())) as Json };
  } catch (error) {
    if (!(error instanceof Error)) throw error;
    const valueErrors = (error as { valueErrors?: readonly string[] }).valueErrors;
    if (error.name === 'ValidationError') return { raises: { error: error.name, value_errors: valueErrors ?? [] } };
    return { raises: { error: error.name, message: error.message } };
  }
}

function expectSame(actual: Outcome, expected: Outcome, label: string): void {
  if (expected.raises !== undefined) {
    expect(actual.raises, label).toEqual(expected.raises);
  } else {
    expect(actual.raises, label).toBeUndefined();
    expect(actual.ok, label).toEqual(expected.ok);
  }
}

describe('design-mode parity with Python', () => {
  it('shares the dimension vocabulary', () => {
    expect([...STYLE_DIMENSIONS]).toEqual(fixture.style_dimensions);
  });

  it('validates and snapshots catalogs', () => {
    expect(fixture.library_cases.length).toBeGreaterThanOrEqual(35);
    for (const c of fixture.library_cases) {
      expectSame(run(() => styleCatalogSnapshot(parseStyleLibrary(c.input))), c, c.name);
    }
  });

  it('looks styles up and lists pending references', () => {
    for (const c of fixture.lookups) {
      if (c.pending !== undefined) expect(pendingReferences(library(c.library)), c.library).toEqual(c.pending);
      else expectSame(run(() => getStyle(c.style_id ?? '', library(c.library))), c, String(c.style_id));
    }
  });

  it('matches style id validation', () => {
    for (const c of fixture.style_ids) {
      expectSame(run(() => parseModel(StyleSelectionSchema, { style_id: c.style_id }, 'StyleSelection')), c, JSON.stringify(c.style_id));
    }
  });

  it('analyses compatibility', () => {
    expect(fixture.compatibility.length).toBeGreaterThanOrEqual(80);
    for (const c of fixture.compatibility) {
      const options = { briefText: c.brief_text, dimensionOverlap: c.dimension_overlap, library: library(c.library) };
      expectSame(run(() => analyzeStyleCompatibility(c.style_ids, options)), c, JSON.stringify(c.style_ids));
    }
  });

  it('compiles prompt text', () => {
    for (const c of fixture.prompts) {
      const composed = c.composed as Parameters<typeof compileDesignPrompt>[1];
      expect(compileDesignPrompt(c.brief as Parameters<typeof compileDesignPrompt>[0], composed)).toBe(c.ok);
    }
    for (const c of fixture.negatives) expect(compileNegativePrompt(c.tokens)).toBe(c.ok);
  });

  it('composes selections by dimension', () => {
    expect(fixture.compose.length).toBeGreaterThanOrEqual(250);
    for (const c of fixture.compose) {
      const brief = c.brief as Parameters<typeof composeStyleSelection>[1];
      expectSame(run(() => composeStyleSelection(c.selections, brief, { library: library(c.library) })), c, JSON.stringify(c.selections));
    }
  }, 60_000);

  it('builds persisted directions', () => {
    for (const c of fixture.directions) {
      const brief = c.brief as Parameters<typeof composeStyleSelection>[1];
      expectSame(run(() => directionFromSelection(c.selection, brief, { library: library(c.library) })), c, JSON.stringify(c.selection));
    }
  }, 60_000);

  it('records unresolved directions', () => {
    for (const c of fixture.unresolved) {
      expectSame(
        run(() => unresolvedDirection(parseDesignStyleSelection(c.selection), c.reason, c.catalog_version)),
        c,
        c.reason,
      );
    }
  });

  it('refuses what Python accepts in lax mode', () => {
    for (const c of fixture.lax_divergences) {
      const attempt = c.kind === 'selection'
        ? () => parseModel(StyleSelectionSchema, c.input, 'StyleSelection')
        : () => parseStyleLibrary(c.input);
      expect(attempt, JSON.stringify(c.input).slice(0, 80)).toThrow();
    }
  });
});
